import '@fontsource/inter/400.css';
import '@fontsource/inter/500.css';
import '@fontsource/inter/600.css';
import '@fontsource/inter/700.css';
import '@fontsource/manrope/400.css';
import '@fontsource/manrope/500.css';
import '@fontsource/manrope/600.css';
import '@fontsource/manrope/700.css';
import '@fontsource/space-grotesk/500.css';
import '@fontsource/space-grotesk/600.css';
import '@fontsource/space-grotesk/700.css';
import {Component,Suspense,lazy,useEffect,useState} from 'react';
import {Bell,Box,Building2,ClipboardList,Compass,LockKeyhole,LogOut,MapPin,ShieldCheck,ShoppingBag,UserRound,Users,Truck,RefreshCw,WalletCards,Moon,Sun} from 'lucide-react';
import {api} from './api';
import {money,useResource} from './data';
import {Brand} from './ui';
import Auth from './Auth';
import ThemeToggle from './ThemeToggle';
import WorkspaceChoice from './WorkspaceChoice';
import DeliveryMap from './DeliveryMap';
import {Addresses,clearPetPush,Notifications,PetCompanion,Profile,useBrowserAlerts} from './common';
import Consumer from './Consumer';
import Manager from './Manager';
import Rider from './Rider';
import Orders from './Orders';
const Community=lazy(()=>import('./Community'));
const Wallet=lazy(()=>import('./Services').then(m=>({default:m.Wallet})));

const AdminUsers=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminUsers})));
const AdminOrders=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminOrders})));
const AdminOverview=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminOverview})));
const AdminDirectory=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminDirectory})));
const AdminRoles=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminRoles})));
const AdminLocks=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminLocks})));
const AdminFinance=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminFinance})));
const AdminAudit=lazy(()=>import('./AdminConsole').then(m=>({default:m.AdminAudit})));
const Security=lazy(()=>import('./Security'));
const Admin=lazy(()=>import('./Admin'));
const AdminAccounts=lazy(()=>import('./Admin').then(m=>({default:m.AdminAccounts})));
const TradeControl=lazy(()=>import('./Admin').then(m=>({default:m.TradeControl})));
const icons={users:Users,platformOrders:Box,overview:Compass,roles:ShieldCheck,locks:LockKeyhole,finance:WalletCards,audit:ClipboardList,browse:Compass,orders:Box,addresses:MapPin,notifications:Bell,security:ShieldCheck,wallet:WalletCards,community:Users,profile:UserRound,organization:Building2,onboarding:Truck,jobs:ClipboardList,dispatch:ClipboardList,reviews:Users,accounts:Users,trade:LockKeyhole};
const navigation={consumer:[['browse','Discover'],['orders','My orders'],['addresses','Delivery map'],['community','Community']],manager:[['organization','Organization'],['orders','Incoming orders']],rider:[['onboarding','Rider profile'],['jobs','Delivery jobs'],['community','Communities']],dispatch:[['dispatch','Dispatch queue']],admin:[['overview','Overview'],['users','Platform users'],['platformOrders','Platform orders'],['accounts','Administrators'],['roles','Roles & permissions'],['reviews','Verification'],['finance','Finance'],['audit','Activity log'],['locks','Page locks'],['trade','Trade controls']]};
const titleCase=s=>s[0].toUpperCase()+s.slice(1);
export default function App({role}){return <ErrorBoundary><Workspace role={role}/></ErrorBoundary>;}
function Workspace({role}){
 const [user,setUser]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[page,setPage]=useState(navigation[role][0][0]);
 useBrowserAlerts(user?.id,role);
 const refresh=async(afterLogin=false)=>{const value=await api('/auth/me');setUser(value.user);if(afterLogin===true){location.assign(value.user.adminLevel?'/admin/':value.user.selectedRole?`/${value.user.selectedRole}/`:'/consumer/');return;}if(role==='consumer'&&new URLSearchParams(location.search).has('entry')&&value.user.selectedRole&&!value.user.adminLevel){location.replace(`/${value.user.selectedRole}/`);return;}if(value.user.adminLevel&&role!=='admin'){location.replace('/admin/');return;}if(!value.user.adminLevel&&role!=='consumer'&&role!==value.user.selectedRole){location.replace('/consumer/');return;}if(role==='admin'&&!value.freshMfa){setPage('security');}else if(role==='admin'&&value.user.adminLevel==='ordinary'){const p=value.user.permissions??[];setPage(p.includes('finance_admin')?'finance':p.some(x=>['organization_verification_admin','rider_verification_admin','warehouse.review'].includes(x))?'reviews':p.includes('security_audit_admin')?'overview':'security');}};
 useEffect(()=>{refresh().catch(e=>{if(e.status!==401)setError(e.message);}).finally(()=>setLoading(false));},[]);
 if(loading)return <main className="boot" role="status"><strong>DEN</strong><p>Connecting your workspace…</p></main>;
 if(!user)return <>{error?<p className="error session-error">{error}</p>:null}<Auth role="DEN" onLogin={()=>refresh(true)}/></>;
 if(role==='admin'&&!user.adminLevel)return <main className="boot"><p>Opening your account…</p></main>;
 const isOwner=user.adminLevel==='primary_super_admin',isSub=user.adminLevel==='lesser_super_admin',permissions=user.permissions??[];
 const adminAllowed=key=>key==='locks'?isOwner:key==='accounts'||key==='roles'?isOwner:key==='overview'||key==='audit'||key==='users'||key==='platformOrders'?isOwner||isSub||permissions.includes('security_audit_admin'):key==='finance'?isOwner||isSub||permissions.includes('finance_admin'):key==='reviews'?isOwner||isSub||permissions.some(p=>['rider_verification_admin','organization_verification_admin','warehouse.review'].includes(p)):key==='trade'?isOwner:true;
 const nav=[...(role==='admin'?navigation.admin.filter(([key])=>adminAllowed(key)):navigation[role]),['profile','Profile'],['wallet','Wallet'],['notifications','Notifications'],['security','Security']];
 let content;
 if(page==='community')content=<Community feed={role==='consumer'}/>;
 else if(page==='wallet')content=<Wallet/>;
 else if(page==='security')content=<Security user={user} onRefresh={refresh}/>;
 else if(page==='profile')content=<Profile/>;
 else if(page==='notifications')content=<Notifications/>;
 else if(page==='addresses')content=<DeliveryMap user={user}/>;
 else if(page==='browse')content=<Consumer onOrders={()=>setPage('orders')}/>;
 else if(page==='organization')content=<Manager user={user}/>;
 else if(page==='onboarding')content=<Rider/>;
 else if(page==='reviews')content=<Admin/>;
 else if(page==='users')content=<AdminUsers/>;
 else if(page==='platformOrders')content=<AdminOrders/>;
 else if(page==='overview')content=<AdminOverview/>;
 else if(page==='accounts')content=<AdminDirectory/>;
 else if(page==='roles')content=<AdminRoles/>;
 else if(page==='locks')content=<AdminLocks/>;
 else if(page==='finance')content=<AdminFinance/>;
 else if(page==='audit')content=<AdminAudit/>;
 else if(page==='trade')content=<TradeControl user={user}/>;
 else content=<Orders role={page==='jobs'?'rider':page==='dispatch'?'dispatch':role}/>;
 return <div className={`app-shell role-${role}`}><a className="skip-link" href="#workspace-content">Skip to content</a><aside className="sidebar"><Brand/><div className="workspace-label">{titleCase(role)} workspace</div><nav aria-label={`${titleCase(role)} navigation`}>{nav.map(([key,label])=>{if(key==='profile'||key==='wallet')return null;const Icon=icons[key];return <button key={key} className={`nav-item ${page===key?'active':''}`} aria-current={page===key?'page':undefined} onClick={()=>setPage(key)}><Icon size={21} strokeWidth={1.7}/>{label}</button>;})}</nav><div className="sidebar-bottom"><div className="trade-status"><LockKeyhole size={20}/><div>International Trade<small>Locked by default</small></div></div><div className="identity"><UserRound size={22}/><div>{user.name}<small>{user.email}</small></div></div><button className="nav-item" onClick={async()=>{try{if(role==='manager'||role==='rider')await clearPetPush().catch(()=>{});await api('/auth/logout','POST',{});setUser(null);}catch(e){setError(e.message);}}}><LogOut size={18}/>Sign out</button></div></aside><div className="workspace"><header className="topbar"><div className="workspace-context"><span className="context-root">DEN Global</span><span className="context-divider">/</span><span className="role-title">{role==='admin'?(isOwner?'Owner Admin':user.adminRole??(isSub?'Sub Admin':'Administrator'))+' · ':''}{nav.find(([key])=>key===page)?.[1]}</span></div>{role==='consumer'?<nav className="account-workspaces" aria-label="DEN workspaces"><a href="/consumer/" aria-current="page">Consumer</a><a href="/pets/">Pet care</a>{!user.adminLevel&&user.selectedRole?<a href={`/${user.selectedRole}/`}>{titleCase(user.selectedRole)}</a>:null}</nav>:!user.adminLevel&&user.selectedRole?<nav className="account-workspaces" aria-label="Your account workspaces"><a href="/consumer/">Consumer</a><a href={`/${user.selectedRole}/`} aria-current="page">{titleCase(user.selectedRole)}</a></nav>:null}<div className="topbar-actions"><HeaderWallet onOpen={()=>setPage('wallet')}/><button type="button" className="profile-access" aria-label="Open profile" title="Profile" onClick={()=>setPage('profile')}><span>{user.name?.trim()?.[0]?.toUpperCase()??<UserRound size={19}/>}</span></button></div><ThemeToggle/></header><main className="main-content" id="workspace-content">{error?<p className="error" role="alert">{error}</p>:null}<Suspense fallback={<p role="status">Loading workspace…</p>}>{role==='consumer'&&!user.selectedRole?<WorkspaceChoice/>:null}{content}</Suspense></main>{role==='manager'||role==='rider'?<PetCompanion userId={user.id} role={role}/>:null}<footer className="workspace-footer">DEN Global · One network. Every journey.<span>Development preview · Live payments and international bookings disabled</span></footer></div></div>;
}
function HeaderWallet({onOpen}){const r=useResource(()=>api('/services/wallet'));const balance=r.data?.balances?.[0];return <button type="button" className="wallet-access" onClick={onOpen} aria-label={balance?`Wallet balance ${money(balance.amountMinor,balance.currency)}`:'Open wallet'}><WalletCards size={18}/><span>Wallet</span><strong>{balance?money(balance.amountMinor,balance.currency):'View balance'}</strong></button>;}
class ErrorBoundary extends Component{state={error:null};static getDerivedStateFromError(error){return{error};}render(){return this.state.error?<main className="boot"><h1>We couldn't open this workspace.</h1><p role="alert">Please reload to reconnect. Your saved server data is retained.</p><button className="primary" onClick={()=>location.reload()}><RefreshCw size={16}/>Reload workspace</button></main>:this.props.children;}}
